function sd_theme_defaults() { return array( 'sd_header_layout' => 'default', 'sd_footer_layout' => 'default', 'sd_primary_color' => '#2563EB', 'sd_primary_hover' => '#1D4ED8', 'sd_secondary_color' => '#7C3AED', 'sd_accent_color' => '#06B6D4', 'sd_header_background' => '#FFFFFF', 'sd_header_text_color' => '#0F172A', 'sd_header_height' => 72, 'sd_header_container_width' => 1240, 'sd_sticky_header' => true, 'sd_header_border' => true, 'sd_header_shadow' => false, 'sd_header_search' => true, 'sd_header_auth' => true, 'sd_header_cta_enabled' => false, 'sd_header_cta_text' => __( 'Join free', 'social-discovery' ), 'sd_header_cta_url' => '', 'sd_mobile_menu_style' => 'drawer', 'sd_footer_background' => '#FFFFFF', 'sd_footer_text_color' => '#64748B', 'sd_footer_heading_color' => '#0F172A', 'sd_footer_description' => '', 'sd_footer_logo' => true, 'sd_footer_columns' => 4, 'sd_copyright' => '', 'sd_footer_social' => true, 'sd_footer_border' => true, 'sd_dark_mode' => 'system', 'sd_reading_width' => 760, 'sd_social_feed_layout' => 'default', 'sd_social_sidebar' => true, 'sd_social_card_style' => 'default', 'sd_social_member_layout' => 'grid', 'sd_social_directory_columns' => 3, 'sd_social_default_sort' => 'active', 'sd_social_suggested_members' => 4, 'sd_social_suggested_communities' => 3, 'sd_communities_layout' => 'grid', 'sd_communities_columns' => 3, 'sd_community_header_layout' => 'cover', 'sd_message_layout' => 'split', 'sd_dashboard_layout' => 'default', 'sd_dashboard_sidebar' => 'left', 'sd_dashboard_compact' => false, 'sd_dashboard_spacing' => 'comfortable', 'sd_notification_card_style' => 'default', 'sd_notification_preview_count' => 5, 'sd_notification_dropdown_width' => 360 ); }
function sd_get_option( $key, $default = null ) { $defaults = sd_theme_defaults(); if ( null === $default && isset( $defaults[ $key ] ) ) { $default = $defaults[ $key ]; } return get_theme_mod( $key, $default ); }
function sd_home_url( $path = '' ) { return esc_url( home_url( '/' . ltrim( $path, '/' ) ) ); }
function sd_is_buddypress() { return function_exists( 'buddypress' ) || function_exists( 'bp_is_active' ); }
function sd_bp_active( $component ) { return function_exists( 'bp_is_active' ) && bp_is_active( $component ); }
